<?php

namespace Database\Seeders;

use Illuminate\Database\Seeder;
use Illuminate\Support\Carbon;
use Illuminate\Support\Facades\DB;

/**
 * Seeds daily inventory and prices (room_inventories) for every active room type.
 *
 * In production this is generated by batch BAT06 for 365 days ahead; here a shorter window keeps
 * seeding fast. Friday and Saturday nights cost 10 % more. New Year's Eve is sold out at
 * Vivu Stay Đà Nẵng to demonstrate the "no availability" state (mockup MB-04e).
 *
 * @author PH.Tuan
 * @created 2026-10-18
 */
class RoomInventorySeeder extends Seeder
{
    /** Number of past days with inventory, so the dashboard can compare with last week. */
    private const DAYS_BEHIND = 7;

    /** Number of days of inventory to create, starting today. */
    private const DAYS_AHEAD = 120;

    /** Weekend surcharge applied to Friday and Saturday nights. */
    private const WEEKEND_SURCHARGE = 1.10;

    /**
     * Run the seeder.
     *
     * @return void
     */
    public function run(): void
    {
        $roomTypes = DB::table('room_types')
            ->join('hotels', 'hotels.id', '=', 'room_types.hotel_id')
            ->where('room_types.status', 'ACTIVE')
            ->select('room_types.id', 'room_types.base_price', 'hotels.code as hotel_code')
            ->get();

        $roomCountsByType = DB::table('rooms')
            ->groupBy('room_type_id')
            ->selectRaw('room_type_id, count(*) as total')
            ->pluck('total', 'room_type_id');

        $firstNight = Carbon::today();
        $soldOutNight = Carbon::create($firstNight->year, 12, 31);

        foreach ($roomTypes as $roomType) {
            $totalRooms = (int) $roomCountsByType[$roomType->id];
            $rows = [];

            for ($offset = -self::DAYS_BEHIND; $offset < self::DAYS_AHEAD; $offset++) {
                $stayDate = $firstNight->copy()->addDays($offset);
                $isSoldOut = $roomType->hotel_code === 'DN' && $stayDate->isSameDay($soldOutNight);

                $rows[] = [
                    'room_type_id' => $roomType->id,
                    'stay_date' => $stayDate->toDateString(),
                    'total_rooms' => $totalRooms,
                    'booked_rooms' => $isSoldOut ? $totalRooms : 0,
                    'blocked_rooms' => 0,
                    'price' => $this->nightlyPrice((int) $roomType->base_price, $stayDate),
                    'stop_sell' => false,
                ];
            }

            DB::table('room_inventories')->insert($rows);
        }
    }

    /**
     * Calculate the price of one night, rounded to 1,000 VND (BR-02).
     *
     * @param  int  $basePrice  Room type base price in VND.
     * @param  Carbon  $stayDate  The night being priced.
     */
    private function nightlyPrice(int $basePrice, Carbon $stayDate): int
    {
        $isWeekendNight = $stayDate->isFriday() || $stayDate->isSaturday();
        $price = $isWeekendNight ? $basePrice * self::WEEKEND_SURCHARGE : $basePrice;

        return (int) (round($price / 1000) * 1000);
    }
}
